#!/usr/bin/env python
"""
Sample code for the Excel-Reader (``xlrd``) toolkit.

This walks through the reading pipeline end to end -- opening a workbook,
accessing sheets, extracting cell data, converting dates, and reporting cell
errors -- and prints what it finds.

Run it from the project root::

    python examples/read_excel.py                        # uses a bundled sample
    python examples/read_excel.py path/to/myfile.xls
"""
from __future__ import print_function

import os
import sys

import xlrd

DEFAULT_SAMPLE = os.path.join(
    os.path.dirname(os.path.dirname(os.path.abspath(__file__))),
    'tests', 'samples', 'profiles.xls',
)


def inspect(path):
    """Report the file format before committing to opening it."""
    file_format = xlrd.inspect_format(path=path)
    print('format: %r (%s)' % (
        file_format, xlrd.FILE_FORMAT_DESCRIPTIONS[file_format],
    ))
    if file_format != 'xls':
        # .xlsx and friends are not supported; openpyxl is the alternative.
        print('  only .xls is supported -- use openpyxl for %s' % file_format)
    return file_format


def describe_workbook(book):
    print('sheets: %d %r' % (book.nsheets, book.sheet_names()))
    print('BIFF version: %s, datemode: %s' % (book.biff_version, book.datemode))


def describe_cell(book, sheet, rowx, colx):
    """Render one cell, resolving dates and error codes to something readable."""
    cell = sheet.cell(rowx, colx)
    ref = '%s%d' % (xlrd.colname(colx), rowx + 1)

    if cell.ctype == xlrd.XL_CELL_DATE:
        try:
            return '%s = %s (date)' % (
                ref, xlrd.xldate_as_datetime(cell.value, book.datemode),
            )
        except xlrd.XLDateError as e:
            return '%s = date error: %s' % (ref, e)

    if cell.ctype == xlrd.XL_CELL_ERROR:
        text = xlrd.error_text_from_code.get(cell.value, 'unknown error')
        return '%s = %s (error)' % (ref, text)

    return '%s = %r (%s)' % (ref, cell.value, xlrd.ctype_text[cell.ctype])


def main(argv=None):
    argv = sys.argv[1:] if argv is None else argv
    path = argv[0] if argv else DEFAULT_SAMPLE

    print('=== reading %s ===' % path)
    if inspect(path) not in ('xls', None):
        return 1

    # Node 1: read from a path, then the same bytes from memory.
    book = xlrd.open_workbook(path)
    describe_workbook(book)
    with open(path, 'rb') as f:
        from_memory = xlrd.open_workbook(file_contents=f.read())
    assert from_memory.nsheets == book.nsheets, 'memory read disagreed'
    print('read from memory: %d sheets (matches)' % from_memory.nsheets)

    # Nodes 2-4: sheet access, then row/column extraction.
    for sheet in book:                       # Book is iterable
        print('\n-- sheet %r: %d rows x %d cols' % (
            sheet.name, sheet.nrows, sheet.ncols,
        ))
        if not (sheet.nrows and sheet.ncols):
            continue

        print('  row 0 values : %r' % (sheet.row_values(0, 0, 3),))
        print('  row 0 types  : %r' % (list(sheet.row_types(0, 0, 3)),))
        print('  col 0 values : %r' % (sheet.col_values(0, 0, 3),))
        print('  row 0 length : %d' % sheet.row_len(0))

        # Nodes 5/7/10: per-cell detail, dates and error codes.
        for colx in range(min(sheet.ncols, 3)):
            print('  %s' % describe_cell(book, sheet, 0, colx))

        # Node 11: merged ranges are only populated with formatting_info=True.
        if sheet.merged_cells:
            for rlo, rhi, clo, chi in sheet.merged_cells:
                print('  merged (%d,%d)-(%d,%d) = %r' % (
                    rlo, clo, rhi - 1, chi - 1, sheet.cell_value(rlo, clo),
                ))

    # Node 7: the documented error paths.
    try:
        book.sheet_by_index(book.nsheets + 10)
    except IndexError:
        print('\nsheet_by_index out of range -> IndexError (as documented)')
    try:
        book.sheet_by_name('no such sheet')
    except xlrd.XLRDError as e:
        print('sheet_by_name unknown -> XLRDError: %s' % e)

    book.release_resources()
    print('\ndone')
    return 0


if __name__ == '__main__':
    sys.exit(main())

